"""Configuration-layer evaluator."""

from copy import deepcopy
import re


_INTEGER_ENV = re.compile(r"-?[0-9]+\Z")


def _failure(error):
    return {"ok": False, "config": {}, "error": error}


def evaluate(request, policy):
    """Apply request configuration layers and optional environment overrides."""
    defaults = policy["defaults"]
    expected_types = policy["types"]
    known = set(defaults)
    config = deepcopy(defaults)

    for layer in request.get("layers", []):
        if any(key not in known for key in layer):
            return _failure("unknown_key")
        for key, value in layer.items():
            if value is None and policy.get("null_resets") is True:
                config[key] = deepcopy(defaults[key])
            else:
                config[key] = value

    environment = request.get("environment", {})
    if policy.get("environment") is True:
        if any(key not in known for key in environment):
            return _failure("unknown_key")
        for key, value in environment.items():
            kind = expected_types.get(key)
            if kind == "boolean":
                if value == "true":
                    config[key] = True
                elif value == "false":
                    config[key] = False
                else:
                    return _failure("environment")
            elif kind == "integer":
                if not isinstance(value, str) or _INTEGER_ENV.fullmatch(value) is None:
                    return _failure("environment")
                config[key] = int(value)
            elif kind == "string":
                config[key] = value
            else:
                return _failure("environment")

    for key, kind in expected_types.items():
        value = config.get(key)
        if kind == "boolean":
            valid = type(value) is bool
        elif kind == "integer":
            valid = type(value) is int
        elif kind == "string":
            valid = type(value) is str
        else:
            valid = False
        if not valid:
            return _failure("type")

    return {"ok": True, "config": config, "error": None}
